effect.shader:
// Advanced Multi-Scale Sharpen
// Inspired by AE/Topaz detail sharpening

vec4 sampleOffset(vec2 uv, vec2 offset) {
    return texture2D(inputImg, uv + offset);
}

// Gaussian blur approximation
vec4 blur(vec2 uv, float radius) {
    vec2 texel = 1.0 / acProjectSize;
    vec4 sum = vec4(0.0);
    sum += sampleOffset(uv, texel * vec2(-radius, 0.0));
    sum += sampleOffset(uv, texel * vec2(radius, 0.0));
    sum += sampleOffset(uv, texel * vec2(0.0, -radius));
    sum += sampleOffset(uv, texel * vec2(0.0, radius));
    sum += texture2D(inputImg, uv);
    return sum / 5.0;
}

void main() {
    vec2 uv = vTexCoord;
    vec4 base = texture2D(inputImg, uv);

    // Multi-scale high-pass details
    vec4 tiny   = base - blur(uv, detailSize * 0.25);
    vec4 small  = base - blur(uv, detailSize * 0.5);
    vec4 medium = base - blur(uv, detailSize * 1.0);
    vec4 large  = base - blur(uv, detailSize * 2.0);

    // Weighted detail mix
    vec4 detailMix = tiny * tinyScale +
                     small * smallScale +
                     medium * mediumScale +
                     large * largeScale;

    // Edge thresholding
    float edgeMask = step(edgeThreshold, length(detailMix.rgb));
    detailMix *= edgeMask;

    // Luma/Chroma separation
    float luma = dot(base.rgb, vec3(0.299, 0.587, 0.114));
    vec3 chroma = base.rgb - luma;

    float sharpenedLuma = luma + dot(detailMix.rgb, vec3(0.333)) * sharpenLuma * sharpenAmp;
    vec3 sharpenedChroma = chroma + detailMix.rgb * sharpenChroma * sharpenAmp;

    // Reconstruct color
    vec3 sharpened = vec3(sharpenedLuma) + sharpenedChroma;

    // Apply RGB multipliers
    sharpened.r *= sharpenR;
    sharpened.g *= sharpenG;
    sharpened.b *= sharpenB;

    gl_FragColor = vec4(sharpened, base.a);
}
